        int idx = 0;
        for (int val = 0; val <= maxVal; val++) {
            for (int c = 0; c < count[val]; c++) {
                result[idx++] = val;
            }
        }
        return result;
    }

    /**
     * LSD radix sort for non-negative integers. O(d * n) time.
     * d is the number of digits in the maximum value.
